import csv, statistics
vals={}
for r in csv.DictReader(open(VALUES_CSV)):
    vals.setdefault(r['timeseries_id'], {})[r['timestamp']]=float(r['value'])

s=vals['e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8']
cp=vals['5b98cbc1-fd25-5d8c-a96e-c3de49819174']
others={'F3Z02':vals['bcc5a78f-36a4-55a0-9420-7a80fc9b2deb'],
        'F3Z03':vals['9c6223f8-3611-5ceb-9107-70e8206e9ccd'],
        'F3Z05':vals['c49bbc2f-096e-5e16-bead-066250790308']}

def monthly(d):
    m={}
    for t,v in d.items():
        m.setdefault(t[:7],[]).append(v)
    return sorted(m.items())

for name,d in [('F3Z01_sensor',s),('F3Z01_coolset',cp)]:
    print(name)
    for t,x in monthly(d):
        print(' ', t, round(statistics.mean(x),2), 'sd=',round(statistics.pstdev(x),2))

# Compare F3Z01 vs others monthly means
print('\nmonth-by-month means:')
months=sorted(set(t[:7] for t in s))
for m in months:
    row=[m]
    row.append(round(statistics.mean([v for t,v in s.items() if t[:7]==m]),2))
    for k,d in others.items():
        row.append(round(statistics.mean([v for t,v in d.items() if t[:7]==m]),2))
    print(row)
